typeUri :: ProblemType -> String
typeUri AboutBlank                  = "about:blank"
typeUri DigestUnsupportedAlgorithms = "https://iana.org/assignments/http-problem-types#digest-unsupported-algorithms"
typeUri MismatchingUploadOffset     = "https://iana.org/assignments/http-problem-types#mismatching-upload-offset"
typeUri InconsistentUploadLength    = "https://iana.org/assignments/http-problem-types#inconsistent-upload-length"

-- | The Title column. For about:blank it says to use the status phrase (PM35).
registryTitle :: ProblemType -> String
registryTitle AboutBlank                  = "See HTTP Status Code"
registryTitle DigestUnsupportedAlgorithms = "Unsupported Hashing Algorithms"
registryTitle MismatchingUploadOffset     = "Mismatching Upload Offset"
registryTitle InconsistentUploadLength    = "Inconsistent Upload Length Values"

-- | The Recommended HTTP Status Code column; about:blank has none ("N/A"), it
-- takes the response's own.
{-@ reflect recommended @-}
recommended :: ProblemType -> Opt Status
recommended AboutBlank                  = Absent
recommended DigestUnsupportedAlgorithms = Present H400_BadRequest
recommended MismatchingUploadOffset     = Present H409_Conflict
recommended InconsistentUploadLength    = Present H400_BadRequest

{-@ reflect isDraft @-}
isDraft :: ProblemType -> Bool
isDraft AboutBlank                  = False
isDraft DigestUnsupportedAlgorithms = False
isDraft MismatchingUploadOffset     = True
isDraft InconsistentUploadLength    = True

-- | Whether the draft's problem types are sent. They are IANA requests, not
-- registrations, so this is off (P UP:RESUMABLE-UPLOAD-13-7.1-1, UP:RESUMABLE-UPLOAD-13-7.1-2, UP:RESUMABLE-UPLOAD-13-7.2-1 (PM23); open question 2).
-- gen-vocab --draft-problem-types turns it on.
{-@ inline draftProblemTypes @-}
draftProblemTypes :: Bool
draftProblemTypes = False

-- | One entry of unsupported_algorithms: the key and the field that named it,
-- as the client sent them (R PD:DIGEST-PROBLEMS-3.1-3, PD:DIGEST-PROBLEMS-3.1-4).
data Unsupported = Unsupported {unsupportedKey :: String, unsupportedField :: String}
  deriving (Eq, Show)

-- | What a draft type's constructor carries besides its members. The field's
-- refinement is 'draftProblemTypes', so while the flag is off LiquidHaskell
-- refuses every construction of a draft type in every core module, whether
-- or not the value later passes through any particular function. The
-- constructor is exported for the exhaustive test, which runs without
-- LiquidHaskell and has to reach every constructor.
data DraftOn = DraftOn
  deriving (Eq, Show)

-- | A problem details object without its status. One constructor per type,
-- carrying that type's members, and a 'DraftOn' if the type is the draft's.
data Problem
  = Blank -- AboutBlank; members: none
  | UnsupportedAlgorithms {unsupportedAlgorithms :: [Unsupported]} -- DigestUnsupportedAlgorithms; members: unsupported_algorithms
  | MismatchingOffset {mismatchingOffsetOn :: DraftOn, expectedOffset :: Int, providedOffset :: Int} -- MismatchingUploadOffset; members: expected-offset, provided-offset
  | InconsistentLength {inconsistentLengthOn :: DraftOn} -- InconsistentUploadLength; members: none
  deriving (Eq, Show)
{-@ data Problem
      = Blank
      | UnsupportedAlgorithms {unsupportedAlgorithms :: [Unsupported]}
