      | InconsistentLength {inconsistentLengthOn :: {w:DraftOn | draftProblemTypes}}
  @-}

{-@ reflect problemType @-}
problemType :: Problem -> ProblemType
problemType Blank                     = AboutBlank
problemType (UnsupportedAlgorithms _) = DigestUnsupportedAlgorithms
problemType (MismatchingOffset _ _ _) = MismatchingUploadOffset
problemType (InconsistentLength _)    = InconsistentUploadLength

-- | A non-about:blank problem fits only its recommended status; about:blank
-- fits any.
{-@ reflect fits @-}
fits :: Problem -> Status -> Bool
fits p s = case recommended (problemType p) of
  Absent -> True
  Present r -> r == s

-- | SF8, the flag half, for every Problem the core holds, however it was
-- built: a draft type exists only while 'draftProblemTypes' is on. It
-- follows from the 'DraftOn' field's refinement, which a match brings into
