{-@ emittable :: p:Problem -> {draftProblemTypes || not (isDraft (problemType p))} @-}
emittable :: Problem -> Proof
emittable Blank                     = ()
emittable (UnsupportedAlgorithms _) = ()
emittable (MismatchingOffset _ _ _) = ()
emittable (InconsistentLength _)    = ()

-- | How the core builds the MismatchingUploadOffset problem: that problem while
-- 'draftProblemTypes' is on, about:blank otherwise, so the response keeps the
-- status the draft requires either way.
{-@ reflect mismatchingOffset @-}
{-@ mismatchingOffset :: m1:Nat -> m2:Nat -> {v:Problem | (draftProblemTypes => v == MismatchingOffset DraftOn m1 m2) && (not draftProblemTypes => v == Blank)} @-}
mismatchingOffset :: Int -> Int -> Problem
mismatchingOffset m1 m2 = if draftProblemTypes then MismatchingOffset DraftOn m1 m2 else Blank

-- | How the core builds the InconsistentUploadLength problem: that problem while
-- 'draftProblemTypes' is on, about:blank otherwise, so the response keeps the
-- status the draft requires either way.
{-@ reflect inconsistentLength @-}
{-@ inconsistentLength :: {v:Problem | (draftProblemTypes => v == InconsistentLength DraftOn) && (not draftProblemTypes => v == Blank)} @-}
inconsistentLength :: Problem
inconsistentLength = if draftProblemTypes then InconsistentLength DraftOn else Blank

{-@ reflect recommendedOk @-}
recommendedOk :: ProblemType -> Bool
recommendedOk t = case recommended t of
  Absent -> True
  Present s -> respondable s

-- | V2 for problems: every recommended status is one a response may carry.
